def parser(log: str) -> dict:
    """结构化解析测试报告，不要用正则扫大日志。"""
    import json
    out = {}
    for chunk in log.split("\n"):
        s = chunk.strip()
        if not s.startswith("{") or '"tests"' not in s:
            continue
        try:
            doc = json.loads(s)
        except Exception:
            continue
        for t in doc.get("tests") or []:
            nodeid = t.get("nodeid")
            outcome = (t.get("outcome") or "").lower()
            if not nodeid:
                continue
            if outcome in ("passed", "xpassed"):
                out[nodeid] = "pass"
            elif outcome in ("failed", "error"):
                out[nodeid] = "fail"
            else:
                out[nodeid] = "skip"
    return out
